class Solution { private fun gcd(first:Int,second:Int):Int{var a=first;var b=second;while(b!=0){val temporary=a%b;a=b;b=temporary};return a};fun countPairs(nums:IntArray,k:Int):Long{val frequency=HashMap<Int,Int>();var answer=0L;for(value in nums){val current=gcd(value,k);for((other,count) in frequency)if(current.toLong()*other%k==0L)answer+=count;frequency[current]=(frequency[current]?:0)+1};return answer} }
